from domus.infrastructure.sqlite_recurrence import SQLiteRecurrences

class SQLiteUnit:
    def __init__(self, connection: sqlite3.Connection, installation: Installation) -> None:
        self.recurrence = SQLiteRecurrences(connection, installation)

    def _transaction(self, *, write: bool) -> Iterator[UnitOfWork]:

                yield SQLiteUnit(connection, self.installation)

    def read(self) -> AbstractContextManager[UnitOfWork]:
        return self._transaction(write=False)

class SQLiteRecurrences(SQLiteRelativeRecurrences):

    def current_schedule_id(self, household_id: str, definition_id: str) -> str | None:
        validate_identifier(household_id)
        validate_identifier(definition_id)
        row = self.connection.execute(
            "SELECT schedule_id FROM recurrence_rules WHERE household_id=? AND definition_id=? "
            "AND state!='retired'",
            (household_id, definition_id),
        ).fetchone()
        if row is None:
            return None
        schedule_id: str = row["schedule_id"]
        validate_identifier(schedule_id)
        return schedule_id

    def schedule(self, household_id: str, schedule_id: str) -> FixedSchedule | None:
        validate_identifier(household_id)
        validate_identifier(schedule_id)
        return _model(
            self.connection.execute(
                "SELECT * FROM recurrence_rules WHERE household_id=? AND schedule_id=? "
                "AND timing_kind='fixed_calendar'",
                (household_id, schedule_id),
            ).fetchone(),
            read_schedule,
            schedule_headers,
        )

